def finalize(invoice):
    # The ledger has no idempotency key, so only retry connect timeouts, where
    # the request never reached the ledger. Read timeouts and connection resets
    # may have been processed, and retrying them could double-post.
    for attempt in range(1, MAX_ATTEMPTS + 1):
        try:
            resp = requests.post(LEDGER_URL, json={"invoice": invoice.id, "amount": invoice.subtotal_cents + invoice.tax_cents}, timeout=10)
            break
        except requests.ConnectTimeout:
            if attempt == MAX_ATTEMPTS:
                raise
            log.warning("invoice_finalize_retry", invoice_id=invoice.id, attempt=attempt)
    resp.raise_for_status()"
}
